// Emit one item per URL so each agent call handles exactly one URL.
const body = $input.first().json.body;
const urls = Array.isArray(body.urls) ? body.urls : [];
const roles = Array.isArray(body.roles) ? body.roles : [];
if (urls.length === 0) throw new Error('No URLs provided in scan payload.');
return urls.map(url => ({ json: { user_id: body.user_id, url, resume_text: body.resume_text || '', location: body.location || '', roles } }));

parameters.text:
=Scrape the following job portal URL for open job listings:

URL: {{ $json.url }}
Target location: {{ $json.location }}
Target roles: {{ $json.roles.join(', ') }}

Use the Crawl4AI tool to fetch content from the URL. Send it a POST request with body:
{"urls": ["{{ $json.url }}"], "crawler_params": {"headless": true}, "extra": {"word_count_threshold": 10}}

From the crawled content, extract all visible job listings and return them as structured JSON.

=Analyze the scraped job listings below against the candidate profile.

Scraped jobs from {{ $('Split URLs').item.json.url }}:
{{ typeof $json.output === 'object' ? JSON.stringify($json.output) : $json.output }}

Candidate profile:
- Resume: {{ $('Split URLs').item.json.resume_text }}
- Location preference: {{ $('Split URLs').item.json.location }}
- Target roles: {{ $('Split URLs').item.json.roles.join(', ') }}

For EACH job in the scraped list produce one analysis object and wrap all results in an "analyses" array.

parameters.jsCode:
// Flatten analyst output into one item per job for individual POSTs to backend.
const raw = $json.output;
const analyses = Array.isArray(raw?.analyses) ? raw.analyses : (Array.isArray(raw) ? raw : []);
const userId = $('Split URLs').item.json.user_id;
const sourceUrl = $('Split URLs').item.json.url;
if (analyses.length === 0) return [];
return analyses.map(job => ({ json: { user_id: userId, source_url: job.source_url || sourceUrl, job_title: job.job_title || '', company: job.company || '', location: job.location || '', skills_required: job.skills_required || [], jd_text: job.jd_text || '', fit_score: typeof job.fit_score === 'number' ? job.fit_score : 0, fit_breakdown: job.fit_breakdown || {}, legitimacy_status: job.legitimacy_status || 'uncertain', legitimacy_note: job.legitimacy_note || '', fit_recommendation: job.fit_recommendation || 'review', fit_summary: job.fit_summary || '' } }));
